const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";
const P2 = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具";

// 1. 读已探测的全部结果
const load = async f => { try { return JSON.parse(await fs.readFile(S+"\\"+f,"utf8")); } catch { return []; } };
const [q, pool, sus, fin, rest] = await Promise.all([
  load("_QUEUE_RESULT.json"), load("_POOL_PROBE.json"), load("_SUSPECTS_RESULT.json"),
  load("_FINAL_RESULT.json"), load("_REST_RESULT.json")
]);
const all = [...pool, ...q, ...sus, ...fin, ...rest];
const good = all.filter(o=>o.verdict==="职位+金额"||o.verdict==="职位列表");

// 2. 筛选「接单/项目制」平台（不是全职招聘）
const GIG_KW = /(freelanc|gig|project|bounty|task|outsourc|marketplace|hire|contract|mission|microtask|work)/i;
const JOB_KW = /(job|career|hiring|recruit|vacancy|position|employ)/i;

const gigs = good.filter(o => {
  const host = String(o.host||"");
  const cat = String(o.cat||"");
  // 分类是接单市场/赏金/数字商品，或域名含 freelance/gig/task 等
  return /接单|赏金|数字商品/.test(cat) || GIG_KW.test(host);
});

// 3. 输出候选，按职位信号排序
const cands = gigs.sort((a,b)=>(b.jobHits||0)-(a.jobHits||0)).map(o=>({
  host: o.host, cat: o.cat, verdict: o.verdict, jobs: o.jobHits||0, money: o.moneyHits||0
}));

return {
  totalProbed: all.length,
  goodTotal: good.length,
  gigCandidates: cands.length,
  top40: cands.slice(0,40),
  // 也存在已有报告中的接单平台
  existingReports: (await fs.readdir(P2)).filter(f=>/平台研究-0[1-9]|平台研究-1[0-9]/.test(f)).slice(0,20)
};
